class Solution {
public:
    int maximalRectangle(vector<vector<char>>& matrix) {
        if (matrix.empty() || matrix[0].empty()) return 0;
        int cols = matrix[0].size();
        vector<int> heights(cols + 1, 0);
        int max_area = 0;
        for (const auto& row : matrix) {
            for (int c = 0; c < cols; c++) {
                heights[c] = (row[c] == '1') ? heights[c] + 1 : 0;
            }
            vector<int> st;
            for (int i = 0; i <= cols; i++) {
                while (!st.empty() && heights[st.back()] > heights[i]) {
                    int h = heights[st.back()];
                    st.pop_back();
                    int w = st.empty() ? i : i - st.back() - 1;
                    max_area = max(max_area, h * w);
                }
                st.push_back(i);
            }
        }
        return max_area;
    }
};

class Solution {
    public int maximalRectangle(char[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) return 0;
        int cols = matrix[0].length;
        int[] heights = new int[cols + 1];
        int maxArea = 0;
        for (char[] row : matrix) {
            for (int c = 0; c < cols; c++) {
                heights[c] = (row[c] == '1') ? heights[c] + 1 : 0;
            }
            int[] st = new int[cols + 2];
            int top = 0;
            for (int i = 0; i <= cols; i++) {
                while (top > 0 && heights[st[top - 1]] > heights[i]) {
                    int h = heights[st[--top]];
                    int w = (top == 0) ? i : i - st[top - 1] - 1;
                    maxArea = Math.max(maxArea, h * w);
                }
                st[top++] = i;
            }
        }
        return maxArea;
    }
}

var maximalRectangle = function(matrix) {
    if (!matrix || matrix.length === 0 || matrix[0].length === 0) return 0;
    const cols = matrix[0].length;
    const heights = new Array(cols + 1).fill(0);
    let maxArea = 0;
    for (let r = 0; r < matrix.length; r++) {
        for (let c = 0; c < cols; c++) {
            heights[c] = matrix[r][c] === '1' ? heights[c] + 1 : 0;
        }
        const st = [];
        for (let i = 0; i <= cols; i++) {
            while (st.length > 0 && heights[st[st.length - 1]] > heights[i]) {
                const h = heights[st.pop()];
                const w = st.length === 0 ? i : i - st[st.length - 1] - 1;
                maxArea = Math.max(maxArea, h * w);
            }
            st.push(i);
        }
    }
    return maxArea;
};
